// tb.v: random-stimulus testbench for RegTop, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg [7:0] a = 8'd0;
    wire [7:0] y;
    reg [7:0] stim [0:239];
    integer i;

    RegTop dut (
        .a(a),
        .y(y)
    );

    task do_reset;
        begin
            #1;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {a} = stim[i];
            #1;
            $display("D %0d %h", i, y);
            #9;
        end
        $finish;
    end
endmodule
